// Posters and validation are generated by default; pass --video to also export MP4.
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {spawn} from 'node:child_process';
import {once} from 'node:events';
import assert from 'node:assert/strict';
import sharp from 'sharp';
const dir=path.dirname(fileURLToPath(import.meta.url)),bundle=path.resolve(process.argv[2]);
const preview=process.argv.includes('--preview'),out=path.resolve(dir,'../IMAGE/07-SW-Overview'),temp=path.join(dir,'temp/rle-color');
await fs.mkdir(temp,{recursive:true});
const trace=JSON.parse(await fs.readFile(path.join(dir,'rle-color-trace.txt'),'utf8'));
trace.lanes=trace.lanes.slice(0,2);
const variant=JSON.parse(await fs.readFile(path.join(dir,'rle-color-variant.txt'),'utf8'));
variant.lanes=variant.lanes.slice(0,2);
const source=await fs.readFile(path.join(dir,'sw-rle-color-sources.lua'),'utf8');
const lua=v=>Array.isArray(v)?'{'+v.map(lua).join(',')+'}':v&&typeof v==='object'?'{'+Object.entries(v).map(([k,v])=>`${k}=${lua(v)}`).join(',')+'}':JSON.stringify(v);
assert(source.includes('local trace='+lua(trace)));
const {createTMath}=await import(pathToFileURL(path.join(bundle,'client.js')));
const runtime=await createTMath('return tmath.scene{theme="pro_white"}','bootstrap.lua',{renderEngine:'cpu',wasmBinary:await fs.readFile(path.join(bundle,'tmath-wasm.wasm'))});
runtime.font('Pretendard',await fs.readFile(path.join(bundle,'Pretendard.ttf')));
const bases=[130,1000],cell=50;
const rgb=v=>[v&255,(v>>>8)&255,(v>>>16)&255];
let checks=0;
const pixel=(frame,w,x,y)=>[...frame.subarray((Math.floor(y)*w+Math.floor(x))*4,(Math.floor(y)*w+Math.floor(x))*4+3)];
const eq=(a,b,where)=>{assert(a.every((v,i)=>Math.abs(v-b[i])<=1),where+': '+a+' / '+b);checks++;};
try {
 runtime.loadLua(source,'sw-rle-color-sources.lua');
 const [width,height]=runtime.size(),duration=runtime.duration,frames=Math.ceil(duration*30)+1;
 let margin=Infinity;const labels=new Set();
 for(let f=0;f<frames;f++) {
  const report=runtime.layoutReport(Math.min(f/30,duration),4);
  const texts=[];
  for(const o of report.objects) {
   if(o.type==='text')assert(o.id.startsWith('label_'),'Unclassified text');
   if(!o.visible||o.type==='group')continue;
   const b=o.paintBounds;assert(b&&b.width>0&&b.height>0,'Invalid bounds '+o.id);
   const m=Math.min(b.x,b.y,width-b.x-b.width,height-b.y-b.height);margin=Math.min(margin,m);assert(m>=4,'Canvas overflow '+o.id);
   if(o.type==='text'){texts.push(o);labels.add(o.id);}
  }
  for(let i=0;i<texts.length;i++)for(let j=i+1;j<texts.length;j++) {
   const a=texts[i].paintBounds,b=texts[j].paintBounds;
   assert(Math.max(a.x-b.x-b.width,b.x-a.x-a.width)>=4||Math.max(a.y-b.y-b.height,b.y-a.y-a.height)>=4,`Text overlap ${texts[i].id}/${texts[j].id}`);
  }
 }
 const memory=trace.lanes.map(()=>new Array(trace.stride*trace.h).fill(trace.background));
 const checkFrame=(frame,name)=>{
  for(let lane=0;lane<bases.length;lane++)for(let y=0;y<trace.h;y++)for(let x=0;x<trace.w;x++) {
   const at=y*trace.stride+x;
   eq(pixel(frame,width,bases[lane]+(x+.5)*cell,1050+(y+.5)*cell),rgb(memory[lane][at]),`${name}: output ${lane}/${at}`);
   eq(pixel(frame,width,bases[lane]+(x+.5)*cell,210+(y+.5)*cell),rgb(trace.lanes[lane].source[at]),`${name}: source ${lane}/${at}`);
  }
 };
 checkFrame(Buffer.from(runtime.render(0,true)),'initial');
 let time=1;const commits=[],gates=[];
 for(let i=0;i<trace.lanes[0].spans.length;i++) {
  const s=trace.lanes[0].spans[i],hold=i===0?.5:.12;
  time+=.12+.30;
  gates.push(time+.05);
  let frame=Buffer.from(runtime.render(time+.05,true));
  for(let lane=0;lane<bases.length;lane++)for(let j=0;j<s.len;j++)
   eq(pixel(frame,width,bases[lane]+(s.x+j+.5)*cell,820),rgb(trace.lanes[lane].source[s.offset+j]),'sample at RLE');
  time+=hold+.18;
  frame=Buffer.from(runtime.render(time+.005,true));
  for(let lane=0;lane<bases.length;lane++)for(let j=0;j<s.len;j++)
   eq(pixel(frame,width,bases[lane]+(s.x+j+.5)*cell,820),rgb(trace.lanes[lane].spans[i].writes[j]),'covered color at RLE');
  time+=.30+.08;
  for(let lane=0;lane<bases.length;lane++)trace.lanes[lane].spans[i].writes.forEach((v,j)=>memory[lane][s.offset+j]=v);
  commits.push(time+.02);checkFrame(Buffer.from(runtime.render(time+.02,true)),`commit ${i}`);
  time+=(s.len>=3?.35:.08)+(i<trace.lanes[0].spans.length-1?.06:0);
 }
 assert(Math.abs(duration-time-3.12)<.002,'Timeline drift');
 const final=Buffer.from(runtime.render(duration,true));checkFrame(final,'final');
 for(let lane=0;lane<bases.length;lane++){assert.deepEqual(memory[lane],trace.lanes[lane].pixels);assert(trace.lanes[lane].verifiedCanvasMatch);}
 runtime.loadLua(source.replace('local trace='+lua(trace),'local trace='+lua(variant)),'color-variant.lua');
 const changed=Buffer.from(runtime.render(runtime.duration,true));
 for(let lane=0;lane<bases.length;lane++)for(let y=0;y<variant.h;y++)for(let x=0;x<variant.w;x++)
  eq(pixel(changed,width,bases[lane]+(x+.5)*cell,1050+(y+.5)*cell),rgb(variant.lanes[lane].pixels[y*variant.stride+x]),'independent engine variant');
 runtime.loadLua(source,'sw-rle-color-sources.lua');
 const report={width,height,duration,frames,framesAudited:frames,labels:labels.size,minMargin:margin,pixelChecks:checks,spans:trace.lanes.map(l=>l.spans.length),canvasMatch:true,variantMatch:true};
 console.log(JSON.stringify(report));
 await fs.writeFile(path.join(temp,'review.txt'),JSON.stringify(report,null,2)+'\nNo additional inline raster review or manual playback; thread raster budget exhausted.\n');
 const longest=trace.lanes[0].spans.reduce((best,s,i,arr)=>s.len>arr[best].len?i:best,0);
 for(const [i,t] of [0,gates[0],gates[longest],commits[longest],duration].entries())
  await sharp(Buffer.from(runtime.render(t,true)),{raw:{width,height,channels:4}}).png().toFile(path.join(temp,'color-review-'+i+'.png'));
 await sharp(final,{raw:{width,height,channels:4}}).webp({lossless:true}).toFile(path.join(out,'rle-color-sources.webp'));
 if (!preview && process.argv.includes('--video')) {
  const ff=spawn('ffmpeg',['-hide_banner','-loglevel','error','-y','-f','rawvideo','-pixel_format','rgba','-video_size',`${width}x${height}`,'-framerate','30','-i','pipe:0','-an','-c:v','libx264','-preset','medium','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',path.join(out,'rle-color-sources.mp4')],{stdio:['pipe','inherit','inherit']});
  const end=once(ff,'close');
  for(let f=0;f<frames;f++) {
   if(!ff.stdin.write(Buffer.from(runtime.render(Math.min(f/30,duration),true))))await once(ff.stdin,'drain');
   if(f%180===0)console.log(`${f}/${frames}`);
  }
  ff.stdin.end();const [code]=await end;assert.equal(code,0);
 }
} finally {runtime.destroy();}
